# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs, factor=10):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: shape
def shape(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(sift(fold(gather(emit(render(raw))))))

